SET NAMES utf8mb4;

DROP TABLE IF EXISTS `w_rune_attribute`;
CREATE TABLE `w_rune_attribute` (
  `rune_type` tinyint NOT NULL COMMENT '紋樣神殿類型: 1=伊娃(Eva), 2=沙哈(Sayha), 3=帕格里奧(Paagrio), 4=殷海薩(Einhasad), 5=馬普勒(Maphr)',
  `rune_name` varchar(50) NOT NULL COMMENT '紋樣名稱',
  `rune_code` varchar(50) NOT NULL COMMENT '紋樣英名代號',
  `level` int NOT NULL COMMENT '紋樣刻印等級 (1~33)',
  `add_str` smallint NOT NULL DEFAULT 0 COMMENT '力量增加',
  `add_dex` smallint NOT NULL DEFAULT 0 COMMENT '敏捷增加',
  `add_con` smallint NOT NULL DEFAULT 0 COMMENT '體質增加',
  `add_int` smallint NOT NULL DEFAULT 0 COMMENT '智力增加',
  `add_wis` smallint NOT NULL DEFAULT 0 COMMENT '精神增加',
  `add_cha` smallint NOT NULL DEFAULT 0 COMMENT '魅力增加',
  `add_ac` smallint NOT NULL DEFAULT 0 COMMENT '防禦增加',
  `add_hp` int NOT NULL DEFAULT 0 COMMENT '血量增加',
  `add_mp` int NOT NULL DEFAULT 0 COMMENT '魔量增加',
  `add_hpr` smallint NOT NULL DEFAULT 0 COMMENT '回血增加',
  `add_mpr` smallint NOT NULL DEFAULT 0 COMMENT '回魔增加',
  `add_dmg` smallint NOT NULL DEFAULT 0 COMMENT '近戰傷害增加',
  `add_hit` smallint NOT NULL DEFAULT 0 COMMENT '近戰命中增加',
  `add_bow_dmg` smallint NOT NULL DEFAULT 0 COMMENT '遠攻傷害增加',
  `add_bow_hit` smallint NOT NULL DEFAULT 0 COMMENT '遠攻命中增加',
  `reduction_dmg` smallint NOT NULL DEFAULT 0 COMMENT '物理傷害減免',
  `magic_reduction` smallint NOT NULL DEFAULT 0 COMMENT '魔法傷害減免',
  `add_mr` smallint NOT NULL DEFAULT 0 COMMENT '魔防增加',
  `add_sp` smallint NOT NULL DEFAULT 0 COMMENT '魔攻增加',
  `add_fire` smallint NOT NULL DEFAULT 0 COMMENT '火屬性抗性',
  `add_wind` smallint NOT NULL DEFAULT 0 COMMENT '風屬性抗性',
  `add_earth` smallint NOT NULL DEFAULT 0 COMMENT '地屬性抗性',
  `add_water` smallint NOT NULL DEFAULT 0 COMMENT '水屬性抗性',
  `add_stun` smallint NOT NULL DEFAULT 0 COMMENT '昏迷耐性',
  `add_stone` smallint NOT NULL DEFAULT 0 COMMENT '石化耐性',
  `add_sleep` smallint NOT NULL DEFAULT 0 COMMENT '睡眠耐性',
  `add_freeze` smallint NOT NULL DEFAULT 0 COMMENT '寒冰耐性',
  `add_sustain` smallint NOT NULL DEFAULT 0 COMMENT '支撐耐性',
  `add_blind` smallint NOT NULL DEFAULT 0 COMMENT '暗黑耐性',
  `add_exp` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '經驗加成%',
  `hp_potion` int NOT NULL DEFAULT 0 COMMENT '藥水恢復增加',
  `add_double_dmg` int NOT NULL DEFAULT 0 COMMENT '雙倍暴擊機率',
  `add_weight` int NOT NULL DEFAULT 0 COMMENT '負重加成',
  `add_pvp_dmg` int NOT NULL DEFAULT 0 COMMENT 'PVP增傷',
  `add_pvp_r` int NOT NULL DEFAULT 0 COMMENT 'PVP減傷',
  PRIMARY KEY (`rune_type`, `level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='五大紋樣神殿刻印階級屬性加成表';

